var t=`0829-chicken-biryani`;var n=`world-0829`;var a=`IN`;var r=`south-asia`;var o=8;var s=158;var g={en:`Chicken Biryani`,ua:`Бір'яні з куркою`};var l={en:`Chicken Biryani is a India dish made with chicken thigh, plain yogurt, ginger-garlic paste, yellow onion. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Бір'яні з куркою, страва кухні країни Індія. Основні складники: куряче стегно, натуральний йогурт, імбирно-часникова паста, жовта цибуля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 80 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 80 хвилин.`,t:[`marinating`],m:80,i:[[`chicken-thigh`,750,`g`],[`plain-yogurt`,170,`g`],[`garam-masala`,8,`g`],[`ground-turmeric`,4,`g`],[`ginger-garlic-paste`,25,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 14 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 14 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:14,i:[[`yellow-onion`,260,`g`],[`ghee`,65,`g`],[`tomato`,210,`g`]]},{en:`Parboil rinsed basmati in abundant water for approximately eight minutes until only partly cooked, then drain for biryani layering.`,ua:`Промитий басматі приваріть у великій кількості води близько восьми хвилин до напівготовності, злийте воду для викладання шарами бір’яні.`,t:[`boiling`],m:8,i:[[`basmati-rice`,440,`g`],[`water`,950,`ml`]]},{en:`In a heavy covered pot alternate seasoned chicken, part-cooked rice, mint, coriander and saffron; keep rice on top.`,ua:`У важкій каструлі з кришкою чергуйте пряну курку, напівготовий рис, м’яту, коріандр і шафран; верхній шар, рис.`,t:[`layered-assembly`],m:12,i:[[`mint`,22,`g`],[`cilantro`,22,`g`],[`saffron-threads`,1,`pinch`]]},{en:`Steam the prepared portions in a covered steamer over gently boiling water for about 32 minutes until completely cooked or set, then remove carefully.`,ua:`Готуйте підготовлені порції на парі під кришкою над слабко киплячою водою близько 32 хвилин до повної готовності чи застигання, обережно вийміть.`,t:[`steaming`],m:32,i:[]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 12 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 12 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:12,i:[]}];var m={slug:t,id:n,country:`IN`,region:r,servings:8,minutes:158,title:g,text:l,steps:h};export{a as country,m as default,n as id,s as minutes,r as region,o as servings,t as slug,h as steps,l as text,g as title};